
class SessionNotConnectedException(Exception):
    """ Raises when connect wasn't used before use of session  """

    def __init__(self):
        super(SessionNotConnectedException, self).__init__()

    def __str__(self):
        return 'Connect was not used before use of session. Please use connect_to_one_click method'


class ApiTypeError(Exception):
    """ Raises an exception for TypeErrors  """

    def __init__(self, error_message):
        super(ApiTypeError, self).__init__()
        self.error_message = error_message

    def __str__(self):
        return self.error_message
